// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    FakeToken collateralToken;
    FakeToken borrowToken;
    FakePriceFeed feed;
    FakePool pool;

    function setUp() public {
        c = new C();
        collateralToken = new FakeToken("Collateral", "COL", 18);
        borrowToken = new FakeToken("Borrow", "BOR", 18);
        feed = new FakePriceFeed();
        pool = new FakePool();

        C.InitializeFeeConfigParams memory f = C.InitializeFeeConfigParams({
            swapFeeAPR: 0,
            fragmentationFee: 1e18,
            liquidationRewardPercent: 1e18,
            overdueCollateralProtocolPercent: 0,
            collateralProtocolPercent: 0,
            feeRecipient: address(0xfee1)
        });
        C.InitializeRiskConfigParams memory r = C.InitializeRiskConfigParams({
            crOpening: 2e18,
            crLiquidation: 15e17,
            minimumCreditBorrowAToken: 1,
            borrowATokenCap: type(uint256).max,
            minTenor: 1,
            maxTenor: 365 days
        });
        C.InitializeOracleParams memory o = C.InitializeOracleParams({
            priceFeed: address(feed),
            variablePoolBorrowRateStaleRateInterval: 1 days
        });
        C.InitializeDataParams memory d = C.InitializeDataParams({
            weth: address(borrowToken),
            underlyingCollateralToken: address(collateralToken),
            underlyingBorrowToken: address(borrowToken),
            variablePool: address(pool)
        });
        c.initialize(address(this), f, r, o, d);
    }

    function testFuzz_property(address actor) public {
        // General rule: c.paused() always reports the true stored pause state.
        // If the caller (whoever it is) manages to pause the protocol, paused() must be true;
        // if the pause attempt reverts (e.g. unauthorized caller), paused() must remain false.
        bool ok;
        vm.prank(actor);
        try c.pause() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == c.paused());
    }
}

contract FakeToken {
    string public name;
    string public symbol;
    uint8 public decimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) {
        name = name_;
        symbol = symbol_;
        decimals = decimals_;
    }

    function totalSupply() external pure returns (uint256) {
        return 0;
    }

    function balanceOf(address) external pure returns (uint256) {
        return 0;
    }
}

contract FakePriceFeed {
    function getPrice() external pure returns (uint256) {
        return 1e18;
    }

    function decimals() external pure returns (uint256) {
        return 18;
    }
}

contract FakePool {}
